// The thumbnail of each new A3 request (reminders send none). The worker serves it against the
// metadata job's media token (D-062). Replace the base URL on import.
const WORKER = 'REPLACE_WITH_WORKER_URL';
const rows = $input.all().filter((item) => item.json.kind === 'REQUEST' && item.json.metadata);
return rows.map(({ json: row }) => {
  const meta = typeof row.metadata === 'string' ? JSON.parse(row.metadata) : row.metadata;
  const shortId = String(row.video_id).slice(0, 8);
  return {
    json: {
      url: `${WORKER}/media/${row.video_id}/${row.version}/${meta.job_id}/thumbnail.jpg?t=${meta.token}`,
      caption: `Video ${shortId} v${row.version} · thumbnail (shot ${meta.thumbnail_shot}) · ${meta.title ?? ''}`.slice(0, 1024),
    },
  };
});

// A3 (D-062): one message per REQUEST/REMINDER row of final_due(), after its thumbnail. Telegram
// text is Vietnamese (D-061); the metadata is quoted as written. Notes come back as a reply to this
// message (WF-06 finds the request by the trailing meta: marker). Callback data: a3:<A|G>:<token>.
const CHECKS = {
  format: 'định dạng',
  size: 'kích thước',
  duration: 'thời lượng',
  loudness: 'âm lượng',
  subtitles: 'phụ đề',
  'black frames': 'khung hình đen',
  silence: 'im lặng',
};
const rows = $input.all().filter((item) => ['REQUEST', 'REMINDER'].includes(item.json.kind) && typeof item.json.token === 'string');
const parse = (value) => (typeof value === 'string' ? JSON.parse(value) : value);
return rows.map(({ json: row }) => {
  const shortId = String(row.video_id).slice(0, 8);
  const meta = parse(row.metadata);
  const header = row.kind === 'REMINDER'
    ? '[AI Video] Nhắc: metadata đang chờ duyệt (A3)'
    : `[AI Video] Metadata sẵn sàng để duyệt (A3, lần ${row.round})`;
  const body = meta
    ? [
        `Tiêu đề: ${meta.title}`,
        '',
        String(meta.description ?? '').slice(0, 1500),
        '',
        `Tag: ${(meta.tags ?? []).join(', ')}`,
        `QA bản 1080p: ${meta.qa_level ?? '?'}`,
        ...(meta.qa ?? [])
          .filter((check) => check.level !== 'PASS')
          .map((check) => `- ${CHECKS[check.name] ?? check.name}: ${check.detail}`),
      ]
    : [`Video: ${row.title ?? '?'}`];
  const text = [
    header,
    `Video ${shortId} v${row.version}`,
    ...body,
    '',
    'Bấm Duyệt để lưu trữ lên Google Drive và hoàn tất video. Bấm Viết lại để Claude viết bản khác, hoặc trả lời (reply) tin này kèm ghi chú.',
    `Hết hạn: ${new Date(row.expires_at).toISOString().replace('T', ' ').slice(0, 16)} UTC`,
    `meta:${row.token}`,
  ].join('\n');
  return { json: { text: text.slice(0, 4096), approve: `a3:A:${row.token}`, regenerate: `a3:G:${row.token}` } };
});

// A verified archive (DONE rows of final_due(), D-062/D-063): where it is, what it cost, and whether
// to delete the Mac copy now. Only the owner's Xóa counts (cleanup_decide); the worker re-verifies
// the archive before deleting. Callback data: cl:<A|R>:<token>.
const rows = $input.all().filter((item) => item.json.kind === 'DONE' && typeof item.json.token === 'string');
const parse = (value) => (typeof value === 'string' ? JSON.parse(value) : value);
const gb = (bytes) => `${(Number(bytes ?? 0) / 1073741824).toFixed(2)} GB`;
const targets = { gdrive: 'Google Drive', nextcloud: 'Nextcloud' };
return rows.map(({ json: row }) => {
  const meta = parse(row.metadata) ?? {};
  const report = parse(row.report) ?? {};
  const cost = Object.entries(report.cost ?? {})
    .map(([currency, total]) => `${Math.round(total * 100) / 100} ${currency}`)
    .join(', ');
  const text = [
    '[AI Video] Video hoàn tất ✓',
    `Video ${String(row.video_id).slice(0, 8)} v${row.version} · ${meta.title ?? row.title ?? '?'}`,
    '',
    `Đã lưu trên ${targets[report.target] ?? report.target} (đã kiểm tra checksum): ${report.path}`,
    `${report.file_count} file, ${(Number(report.total_bytes ?? 0) / 1048576).toFixed(1)} MB`,
    `Chi phí: ${cost || 'chưa ghi nhận'} · agent ${report.agent_minutes ?? 0} phút · ${report.jobs ?? '?'} job`,
    `Hashtag: ${(meta.hashtags ?? []).join(' ')}`,
    '',
    `Xóa bản trên Mac (${gb(report.local_bytes)}) để giải phóng chỗ? Chỉ chủ sở hữu bấm được; worker kiểm tra lại bản lưu trước khi xóa. Không trả lời trong 7 ngày thì giữ lại.`,
  ].join('\n');
  return { json: { text: text.slice(0, 4096), approve: `cl:A:${row.token}`, reject: `cl:R:${row.token}` } };
});

// The Mac copy was deleted after the owner's approval and a fresh check of the archive (D-063).
const rows = $input.all().filter((item) => item.json.kind === 'CLEANED');
const parse = (value) => (typeof value === 'string' ? JSON.parse(value) : value);
return rows.map(({ json: row }) => {
  const report = parse(row.report) ?? {};
  const text = [
    `[AI Video] Đã xóa bản trên Mac: ${(Number(report.freed_bytes ?? 0) / 1073741824).toFixed(2)} GB`,
    `Video ${String(row.video_id).slice(0, 8)} v${row.version} · ${row.title ?? '?'}`,
    `Bản lưu (đã kiểm tra lại ngay trước khi xóa): ${report.remote_dir}`,
  ].join('\n');
  return { json: { text } };
});
